proofs.formal_signature:
@FiniteQM.CatalogueGeometry.extreme_of_unique_affine_max : ∀ {n : ℕ} (S : Set (FiniteQM.ReconstructionGeometry.Space n))
  (f : FiniteQM.ReconstructionGeometry.Space n →ᵃ[ℝ] ℝ),
  ∀ z ∈ S, (∀ x ∈ S, f x ≤ f z) → (∀ x ∈ S, f x = f z → x = z) → z ∈ Set.extremePoints ℝ S

@FiniteQM.ConcreteJordanProducts.classical_add_left : ∀ {r : ℕ} (a b c : Fin r → ℝ),
  FiniteQM.ConcreteJordanProducts.classicalMul (a + b) c =
    FiniteQM.ConcreteJordanProducts.classicalMul a c + FiniteQM.ConcreteJordanProducts.classicalMul b c

@FiniteQM.ConcreteJordanProducts.classical_normalized : ∀ {r : ℕ} (a : Fin r → ℝ),
  FiniteQM.ConcreteJordanProducts.classicalPositive a ∧ FiniteQM.ConcreteJordanProducts.classicalTrace a = 1 ↔
    a ∈ stdSimplex ℝ (Fin r)

@FiniteQM.ClassicalModel.coord_one_unique : ∀ {n : ℕ} {x : FiniteQM.ReconstructionGeometry.Space n},
  x ∈ FiniteQM.ClassicalModel.states n →
    ∀ (i : Fin (n + 1)), ((FiniteQM.ClassicalModel.basis n).coord i) x = 1 → x = (FiniteQM.ClassicalModel.basis n) i

@FiniteQM.ClassicalModel.coords_probability : ∀ {n : ℕ} {x : FiniteQM.ReconstructionGeometry.Space n},
  x ∈ (FiniteQM.ClassicalModel.system n).states →
    (FiniteQM.ClassicalModel.basis n).coords x ∈ stdSimplex ℝ (Fin (n + 1))
